\begin{align*}
\dfrac{\text{Pow}(A, (PFXQ))}{\text{Pow}(A , (GFXD))} &= \dfrac{AF^2}{AG^2} 
&= \dfrac{\sin^2 \angle AGF}{\sin^2 \angle AFG} 
&\stackrel{\color{red}\cong ~ \triangle}{=} \dfrac{\sin^2 \angle XDQ}{\sin^2 \angle DFG} 
&\stackrel{\color{blue}\sim ~ \triangle}{=} \dfrac{\sin^2 \angle EDC}{\sin^2 \angle EFX} 
