draw(A--B--C--cycle, orange); draw(B--Q^^C--P, lightmagenta); draw(P--M--B, deepgreen+linewidth(1.2)); draw(Q--M--C, deepgreen+linewidth(1.2)); draw(B--R--C, blue); draw(M--R, dashed);

string[] names = {" $A$ ", " $B$ ", " $C$ ", " $M$ ", " $N$ ", " $O$ ", " $P$ ", " $Q$ ", " $R$ "};
